def update_memories(facts, memories, policies, updates):
    changes = {}

    for update in updates:
        update_date = datetime.strptime(update['observed'], '%Y-%m-%d')

        for fact in facts:
            fact_date = datetime.strptime(fact['observed'], '%Y-%m-%d')

            if fact_date > update_date:
                continue

            if fact['id'] == update['id']:
                continue

            for policy in policies:
                policy_support = policy_supports(policy, fact, facts)

                if policy_support is None:
                    continue

                if policy_support['credibility'] == 'low':
                    changes[fact['id']] = 'uncertain'
                elif policy_support['credibility'] == 'false':
                    changes[fact['id']] = 'withdraw'
                elif policy_support['credibility'] == 'replaced':
                    changes[fact['id']] = 'recompute'

    return changes

